<span class="line"><span style="color:#B392F0;">sudo</span><span style="color:#9ECBFF;"> sed</span><span style="color:#79B8FF;"> -i</span><span style="color:#9ECBFF;"> &#39;/swap/s/^/#/&#39;</span><span style="color:#9ECBFF;"> /etc/fstab</span></span>
